  ('c4da193a-17de-4b0d-aab2-67c746a0b04a', $$Economie$$, $$VWO$$, $$Vrouwenvoetbal$$, $$VWO Economie 2021-III$$),
  ('92270fc4-c4b6-4455-9ff3-ad789e0cbf10', $$Economie$$, $$VWO$$, $$Pensioenleeftijd$$, $$VWO Economie 2021-III$$),
  ('446af45b-da99-4b1e-9ee6-d74bd82bf81c', $$Economie$$, $$VWO$$, $$Een CO₂-taks$$, $$VWO Economie 2021-III$$),
