insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('9c8cf75a-a294-4d10-9e27-897c9b077efa', 'c4da193a-17de-4b0d-aab2-67c746a0b04a', $$inleiding: begrotingsregel van de voetbalbond$$,
   $$economie-vwo-2021-iii-vrouwenvoetbal-context1.png$$,
   $$Vrouwenvoetbal ontwikkelt zich snel en de verwachting is dat clubs hoge salarissen gaan betalen voor topspeelsters. De nationale voetbalbond wil voorkomen dat clubs zich in de schulden steken om speelsters aan te trekken. Mede daarom eist de bond van de clubs een begrotingsregel: de kosten van een jaar mogen niet hoger zijn dan de opbrengsten, op straffe van puntenaftrek of zelfs degradatie naar een lagere klasse. De voorzitter van de bond stelt dat deze begrotingsregel invloed heeft op de marktwaarde van speelsters.$$, 'inline'),
  ('8d76a6a6-df19-438b-9736-41e26984041b', 'c4da193a-17de-4b0d-aab2-67c746a0b04a', $$voetbalclub VV: twee beloningsvarianten voor een nieuwe speelster$$,
   $$economie-vwo-2021-iii-vrouwenvoetbal-context2.png$$,
   $$Voetbalclub VV (Vrouwen Vooruit) heeft een betaald team dat speelt in de hoogste divisie. De club heeft als doelstelling om dit jaar kampioen te worden en wil een ervaren speelster aantrekken. Tot op heden hebben speelsters een vast salaris (variant 1), maar bij het aantrekken van een nieuwe speelster overweegt directeur Verheijen ook een variabele variant:
− Variant 1: een vast salaris van € 30.000 per jaar.
− Variant 2: een vast salaris van € 12.000 per jaar + € 1.100 per gespeelde wedstrijd. In de competitie worden 30 wedstrijden gespeeld. De speelsters worden vier dagdelen per week op de club verwacht voor trainingen. Zij worden daarnaast geacht zelfstandig te trainen om hun conditie op peil te houden om wedstrijden te kunnen spelen. De meeste speelsters hebben naast inkomsten uit het voetbal nog andere inkomsten.$$, 'inline'),
  ('d948c378-e1f5-4af0-8a25-0197249722cd', 'c4da193a-17de-4b0d-aab2-67c746a0b04a', $$verwachting: averechtse selectie bij variant 1$$,
   $$economie-vwo-2021-iii-vrouwenvoetbal-context3.png$$,
   $$Directeur Verheijen verwacht dat er bij het aanbieden van variant 1 eerder averechtse selectie kan optreden dan bij variant 2.$$, 'inline'),
  ('6b616668-6adf-4dc3-8a19-2129fa50722e', 'c4da193a-17de-4b0d-aab2-67c746a0b04a', $$directeur: bezoekersaantallen moeten omhoog$$,
   $$economie-vwo-2021-iii-vrouwenvoetbal-context4.png$$,
   $$Directeur Verheijen zegt: “De begroting in tabel 1 laat nu een kleine plus zien zonder de extra speelster. Als we geen verlies willen lijden en toch een extra speelster willen aantrekken, dan zullen de bezoekersaantallen omhoog moeten.”$$, 'inline'),
  ('976e7623-0a27-45a5-92f8-355981305e2e', 'c4da193a-17de-4b0d-aab2-67c746a0b04a', $$tabel 1: resultatenbegroting 2021 zonder extra speelster$$,
   $$economie-vwo-2021-iii-vrouwenvoetbal-context5.png$$,
   $$Tabel 1 Resultatenbegroting 2021 zonder extra speelster (in euro’s)
kosten | | opbrengsten |
Vaste salarissen | 480.000 | Sponsorbijdragen* | 466.000
Overige constante kosten* | 216.000 | Televisierechten* | 80.000
Totale variabele kosten (proportioneel afhankelijk van aantal bezoekers) | 18.000 | Entreegelden: 18.000 bezoekers x €10* | 180.000
Winst | 12.000 | |
| 726.000 | | 726.000
* Deze bedragen worden verondersteld niet te veranderen bij onderstaande vragen.$$, 'inline'),
  ('57e2c4b5-3a7e-4398-8d18-5402e34c8844', 'c4da193a-17de-4b0d-aab2-67c746a0b04a', $$jeugdopleiding en vergoeding bij vertrek voor 20ste levensjaar$$,
   $$economie-vwo-2021-iii-vrouwenvoetbal-context6.png$$,
   $$Directeur Verheijen ziet graag jeugdspeelsters doorgroeien van het jeugdteam naar het betaalde elftal. Hij wil extra investeren in de jeugdopleiding door middel van betere faciliteiten en een betere begeleiding. Hij voorziet wel een berovingsprobleem. Hij denkt dit probleem te kunnen beperken door de volgende maatregel: speelsters die voor hun 20ste levensjaar vertrekken bij de club moeten VV een vergoeding betalen.$$, 'inline'),
  ('b37424a5-6d20-46ce-bd28-cf8cf2449bf3', '92270fc4-c4b6-4455-9ff3-ad789e0cbf10', $$inleiding: AOW en aanvullend pensioen; ontwikkelingen A en B$$,
   $$economie-vwo-2021-iii-pensioenleeftijd-context1.png$$,
   $$Het pensioen bestaat in een land voor de meeste mensen uit AOW en (tegelijkertijd) het aanvullend pensioen. De AOW wordt betaald uit premies die onderdeel zijn van de inkomensheffing, en is bestemd voor iedere ingezetene, ongeacht of men heeft gewerkt. Het aanvullend pensioen wordt gefinancierd volgens het kapitaaldekkingsstelsel. De betaalbaarheid van de pensioenen is onder druk komen te staan door onderstaande demografische ontwikkelingen:
− A: de laatste jaren is het aantal gepensioneerden toegenomen, terwijl de werkzame beroepsbevolking constant is gebleven.
− B: de levensverwachting in dit land neemt toe.$$, 'inline'),
  ('5bb051f6-6556-4bf7-98b7-c6193af1e23e', '92270fc4-c4b6-4455-9ff3-ad789e0cbf10', $$econoom: slechts één ontwikkeling leidt tot financieringsproblemen$$,
   $$economie-vwo-2021-iii-pensioenleeftijd-context2.png$$,
   $$Een econoom stelt dat bij de aanvullende pensioenen slechts één van deze twee ontwikkelingen tot financieringsproblemen leidt.$$, 'inline'),
  ('d613b7ef-5539-4856-8ad2-1d4a9ce3c370', '92270fc4-c4b6-4455-9ff3-ad789e0cbf10', $$koppeling AOW-leeftijd aan de levensverwachting$$,
   $$economie-vwo-2021-iii-pensioenleeftijd-context3.png$$,
   $$Om de betaalbaarheid van de AOW te verbeteren is enige tijd geleden de AOW gekoppeld aan de gemiddelde levensverwachting: voor elk jaar dat de gemiddelde levensverwachting stijgt, wordt de AOW-leeftijd met acht maanden verhoogd.$$, 'inline'),
  ('1594a7f4-2885-40bc-a713-dd1c9fee0ed6', '92270fc4-c4b6-4455-9ff3-ad789e0cbf10', $$politicus wil koppeling afschaffen en pensioenleeftijd verlagen$$,
   $$economie-vwo-2021-iii-pensioenleeftijd-context4.png$$,
   $$Een politicus wil deze koppeling in 2022 afschaffen en bovendien de pensioenleeftijd verlagen. De econoom verwacht dat het overheidssaldo zal verslechteren door deze maatregel.$$, 'inline'),
  ('183689b4-b44f-44b9-b5b8-3b638a44e5e4', '92270fc4-c4b6-4455-9ff3-ad789e0cbf10', $$figuur 1: factoren die de premie van het aanvullend pensioen bepalen$$,
   $$economie-vwo-2021-iii-pensioenleeftijd-context5.png$$,
   $$Figuur 1 Factoren die de hoogte van de premie van het aanvullend pensioen bepalen
Pijlen naar ‘Premiehoogte’:
a: te verwachten beleggingsopbrengst
b: aantal maanden dat premie wordt betaald
c: aantal maanden dat uitkeringen worden ontvangen
d: hoogte van de pensioenuitkering$$, 'inline'),
  ('22d6d918-4acf-4467-b496-8407cdbe6764', '92270fc4-c4b6-4455-9ff3-ad789e0cbf10', $$econoom: koppeling kan premie aanvullend pensioen verlagen$$,
   $$economie-vwo-2021-iii-pensioenleeftijd-context6.png$$,
   $$De econoom legt de voordelen van de koppeling uit: “De koppeling van de AOW-leeftijd aan de levensverwachting kan leiden tot een verlaging van de premie voor het aanvullend pensioen.” Op basis van figuur 1 geeft de econoom daarvoor drie verklaringen.$$, 'inline'),
  ('5acfd8e9-e2bc-4935-a176-a42e1107338f', '92270fc4-c4b6-4455-9ff3-ad789e0cbf10', $$econoom vreest premieverhoging en druk op de export$$,
   $$economie-vwo-2021-iii-pensioenleeftijd-context7.png$$,
   $$De econoom vreest dat wanneer er geen extra maatregelen worden genomen, de premies voor het aanvullend pensioen en de AOW moeten worden verhoogd om de pensioenen betaalbaar te houden. De export kan hierdoor onder druk komen te staan.$$, 'inline'),
  ('b1e80313-a781-4f78-921f-0027515bb14a', '92270fc4-c4b6-4455-9ff3-ad789e0cbf10', $$politicus: welvaartsvaste AOW zonder lastenverzwaring$$,
   $$economie-vwo-2021-iii-pensioenleeftijd-context8.png$$,
   $$De politicus vindt een verhoging van de AOW-leeftijd acceptabel als daar tegenover staat dat de uitkeringen welvaartsvast worden zonder premieverhoging. De politicus beweert: “Als door de verhoging van de AOW-leeftijd de verhouding tussen de AOW-gerechtigden en de werkenden gelijk kan blijven, dan kan de AOW welvaartsvast worden zonder lastenverzwaring voor de werkenden (premieplichtigen).”$$, 'inline'),
  ('6e6028b2-40bb-440e-9e5d-6b61b00ff9df', '92270fc4-c4b6-4455-9ff3-ad789e0cbf10', $$formule premiepercentage AOW$$,
   $$economie-vwo-2021-iii-pensioenleeftijd-context9.png$$,
   $$Premiepercentage AOW = (Totaal bedrag AOW-uitkeringen / Totaal bruto-inkomen premieplichtigen) x 100%$$, 'inline'),
  ('dbff306b-0115-477c-93a3-d0ac83f7a9e4', '446af45b-da99-4b1e-9ee6-d74bd82bf81c', $$inleiding: CO₂-taks en het CO₂-lek$$,
   $$economie-vwo-2021-iii-een-co2-taks-context1.png$$,
   $$In 2015 ondertekende de Nederlandse overheid het klimaatverdrag van Parijs waarin internationaal werd afgesproken om maatregelen te nemen om de uitstoot van CO₂ door bedrijven en gezinnen sterk te beperken. De Nederlandsche Bank (DNB) onderzoekt in dit kader de gevolgen van een belasting op CO₂-uitstoot, de CO₂-taks. Als Nederland een CO₂-taks invoert en de andere landen niet, zal de kostprijs bij Nederlandse bedrijven stijgen. Dit zal leiden tot een verslechtering van de internationale concurrentiepositie. Hierdoor kan het zogenoemde CO₂-lek ontstaan: in Nederland daalt de uitstoot van CO₂ maar de totale mondiale uitstoot daalt niet.$$, 'inline'),
  ('290b62fa-b046-4bf2-81b6-34e48cf9305b', '446af45b-da99-4b1e-9ee6-d74bd82bf81c', $$DNB-econoom: rol van exportbedrijven bij mondiale uitstoot$$,
   $$economie-vwo-2021-iii-een-co2-taks-context2.png$$,
   $$Een DNB-econoom stelt (gegeven de beschreven context) dat de CO₂-taks juist bij de exportbedrijven een grote rol kan spelen bij het terugdringen van de mondiale CO₂-uitstoot.$$, 'inline'),
  ('193d4514-5403-450c-9005-e2ce398da89c', '446af45b-da99-4b1e-9ee6-d74bd82bf81c', $$CO₂-taks verhoogt kostprijs exportproducten met 1,2%$$,
   $$economie-vwo-2021-iii-een-co2-taks-context3.png$$,
   $$Uit doorrekening van de rekenmodellen blijkt dat door een CO₂-taks van
50 euro per ton CO₂ de kostprijs van Nederlandse exportproducten gemiddeld zal stijgen met 1,2%. Deze CO₂-taks heeft ook een effect op het buitenlandse prijspeil.$$, 'inline'),
  ('fdc1c95f-7dd7-484a-8723-139d4dea24af', '446af45b-da99-4b1e-9ee6-d74bd82bf81c', $$gevoeligheid voor internationale concurrentie per sector$$,
   $$economie-vwo-2021-iii-een-co2-taks-context4.png$$,
   $$DNB schrijft dat de gevoeligheid voor internationale concurrentie per sector verschilt. Een indicatie voor deze concurrentiegevoeligheid is het niveau van openheid van een bedrijfstak zoals te zien is in figuur 1.$$, 'inline'),
  ('48283669-7db5-41ac-bfd3-b660e7c6284a', '446af45b-da99-4b1e-9ee6-d74bd82bf81c', $$figuur 1: openheid van Nederlandse bedrijfstakken$$,
   $$economie-vwo-2021-iii-een-co2-taks-context5.png$$,
   $$Figuur 1 Openheid van Nederlandse bedrijfstakken
Som van import en export in procenten van bruto toegevoegde waarde, 2016
Staafdiagram (schaal 0-400) voor: totaal economische activiteiten, landbouw en veeteelt, delfstoffenwinning, verwerkende industrie, waarvan chemie, waarvan basismetaal, energiebedrijven, water- en afvalwaterbedrijven, bouw, diensten, waarvan transport.$$, 'inline'),
  ('9bff77f0-0f93-41f5-84e0-8ddbc6afb4fc', '446af45b-da99-4b1e-9ee6-d74bd82bf81c', $$stelling: sterker effect op chemiesector dan op bouwsector$$,
   $$economie-vwo-2021-iii-een-co2-taks-context6.png$$,
   $$De DNB-econoom stelt op basis van figuur 1 dat de invoering van een CO₂-taks een sterker negatief effect heeft op de winstgevendheid van de chemiesector dan op de winstgevendheid van de bouwsector.$$, 'inline'),
  ('d2c4db1a-b770-4abd-a915-157d7105d114', '446af45b-da99-4b1e-9ee6-d74bd82bf81c', $$vraag- en aanbodmodel chemische sector: doorberekening aan consument$$,
   $$economie-vwo-2021-iii-een-co2-taks-context7.png$$,
   $$In een vraag- en aanbodmodel van de chemische sector berekent de DNB-econoom het effect van de CO₂-taks van 2,5% op de evenwichtsprijs. Hieruit blijkt dat, gegeven een prijselasticiteit van de vraag van -2, de gevraagde hoeveelheid zal dalen met 4,3%. De DNB-econoom beweert dat meer dan driekwart van de CO₂-taks uiteindelijk zal worden doorberekend aan de consument.$$, 'inline'),
  ('4ce71820-f563-4f2e-a7fa-40cf218ac594', '446af45b-da99-4b1e-9ee6-d74bd82bf81c', $$simulatie: drie bestemmingen van de opbrengsten$$,
   $$economie-vwo-2021-iii-een-co2-taks-context8.png$$,
   $$De DNB-econoom simuleert de effecten van de CO₂-taks op de Nederlandse economie in een model. In tabel 1 zijn drie bestemmingen opgenomen van de opbrengsten van de CO₂-taks van de overheid.$$, 'inline'),
  ('4e82eecc-b359-4cc1-b7ac-16791eb359a5', '446af45b-da99-4b1e-9ee6-d74bd82bf81c', $$tabel 1: macro-economische effecten van de CO₂-taks$$,
   $$economie-vwo-2021-iii-een-co2-taks-context9.png$$,
   $$Tabel 1 Macro-economische effecten van CO₂-taks
bestemming van extra belastinginkomsten: verbetering begrotingssaldo | verlaging inkomstenbelasting | verlaging winstbelasting
bruto binnenlands product (% mutatie) | -0,9 | 0,5 | -0,4
reëel beschikbaar huishoudinkomen (% mutatie) | -2,5 | 1,8 | -1,9
particuliere consumptie (% mutatie) | -2,1 | 2,2 | -1,6
bedrijfsinvesteringen (% mutatie) | -2,0 | -0,5 | 3,4
uitvoer goederen en diensten (% mutatie) | -0,5 | -0,5 | -0,1
werkloosheid (% beroepsbevolking) | 0,6 | -0,4 | 0,3
begrotingssaldo (% bbp) | 0,6 | 0,3 | -0,4
Toelichting: getallen zijn cumulatieve effecten in procenten na vijf jaar$$, 'inline'),
  ('b24bbfab-e36d-4554-83c6-46ddf616300d', '446af45b-da99-4b1e-9ee6-d74bd82bf81c', $$conclusie: kies de minst negatieve bestemming$$,
   $$economie-vwo-2021-iii-een-co2-taks-context10.png$$,
   $$De DNB-econoom concludeert dat de overheid die bestemming moet kiezen waarbij de macro-economische effecten per saldo het minst negatief uitpakken.$$, 'inline'),
  ('7751e0aa-9977-4ebe-9cec-b8489075c5f9', '40592b61-0e93-413e-81c4-1708f153c526', $$inleiding: ziekenhuizen en vier grote zorgverzekeraars$$,
   $$economie-vwo-2021-iii-gezonde-zorg-context1.png$$,
   $$Ziekenhuiszorg wordt in Nederland aangeboden door meer dan 300 ziekenhuizen. De ziekenhuizen zijn zelfstandige, particuliere organisaties. Zorgverzekeraars sluiten contracten met ziekenhuizen over de prijs en de hoeveelheid zorg die wordt geboden aan de vragers naar zorg (de verzekerden). De vier grootste zorgverzekeraars hebben samen 80% van de zorgverzekeringsmarkt in handen.$$, 'inline'),
  ('cc27cc82-fdb1-49eb-9269-6df32f36a12b', '40592b61-0e93-413e-81c4-1708f153c526', $$onderhandeling over prijs van € 1.000 per behandeling$$,
   $$economie-vwo-2021-iii-gezonde-zorg-context2.png$$,
   $$Een redactrice van een economisch magazine schrijft een artikel over specialisatie van behandelingen bij ziekenhuizen. Ze richt zich op een bepaalde behandeling waarin patiënten uit een regio alleen terecht kunnen bij één ziekenhuis. Voor 2021 onderhandelen de vier grootste zorgverzekeraars gezamenlijk met het ziekenhuis over een contract. De gezamenlijke zorgverzekeraars stellen een prijs van € 1.000 per behandeling voor. Het ziekenhuis vindt dat onacceptabel, omdat er dan verlies wordt geleden op deze behandeling. Het ziekenhuis dreigt het aantal behandelingen te beperken. Hierdoor zullen de wachtlijsten langer worden.$$, 'inline'),
  ('b26df3ab-47d8-483a-9522-c527ea71a267', '40592b61-0e93-413e-81c4-1708f153c526', $$kostenfunctie van de behandeling$$,
   $$economie-vwo-2021-iii-gezonde-zorg-context3.png$$,
   $$Voor deze behandeling geldt in 2021 de volgende kostenfunctie:
TK = 101Q² – 10Q + 3.500
TK = totale kosten per dag in euro’s
Q = aantal behandelingen per dag$$, 'inline'),
  ('4a9ab593-cd37-4b36-a9fb-1a249f1fa2a7', '40592b61-0e93-413e-81c4-1708f153c526', $$voorstel ziekenhuis: winst 15% van de omzet; voorwaarden zorgverzekeraars$$,
   $$economie-vwo-2021-iii-gezonde-zorg-context4.png$$,
   $$Het ziekenhuis komt met een voorstel aan de zorgverzekeraars. De prijs van deze behandeling wordt zodanig vastgesteld dat de winst 15% van de omzet van deze behandeling bedraagt. Voor de overige zorg gaat het ziekenhuis akkoord met een lagere prijs. De zorgverzekeraars gaan akkoord met dit voorstel en stellen twee voorwaarden voor de hogere prijs van deze behandeling:
− Het aantal behandelingen moet worden uitgebreid naar 10 per dag.
− Het ziekenhuis moet deze behandelmethode innoveren. Als gevolg van deze specifieke investering zullen de constante (vaste) kosten van deze behandeling stijgen met 20%.$$, 'inline'),
  ('4e30a0bc-8c6c-4c2d-bd90-75f35b4bd9a3', '40592b61-0e93-413e-81c4-1708f153c526', $$redactrice: ziekenhuis moet een meerjarig contract eisen$$,
   $$economie-vwo-2021-iii-gezonde-zorg-context5.png$$,
   $$De redactrice schrijft: “Ik verwacht dat als het ziekenhuis akkoord gaat met de voorwaarden voor alleen het aankomende jaar, dat de zorgverzekeraars na 2021 mogelijk een lagere prijs per behandeling afdwingen door te dreigen een ander ziekenhuis in de regio te benaderen om in de toekomst deze behandeling uit te voeren. Het ziekenhuis zal een meerjarig contract moeten eisen.”$$, 'inline'),
  ('24d52e10-5f1e-448d-9781-21887938113f', '40592b61-0e93-413e-81c4-1708f153c526', $$redactrice: twee argumenten over hogere prijsstijging$$,
   $$economie-vwo-2021-iii-gezonde-zorg-context6.png$$,
   $$In haar artikel beschrijft de redactrice dat de overheidsdoelstelling van betaalbare zorg met deze onderhandelingssituatie het best wordt gediend. De redactrice concludeert: “De prijsstijging van deze behandelmethode zou hoger zijn geweest als: – de zorgverzekeraars geen marktleider zouden zijn op de oligopolistische markt van de zorgverzekeringen. – er meerdere ziekenhuizen zouden zijn die de behandeling kunnen en willen uitvoeren.”$$, 'inline'),
  ('7870dad9-8a73-459e-806e-40693b3c2acc', '55a29243-fb93-4dcc-9522-2916f163ec57', $$inleiding: vergrijzing en dalende arbeidsdeelname$$,
   $$economie-vwo-2021-iii-maatregelen-die-werken-context1.png$$,
   $$In een land is sprake van vergrijzing en een dalende arbeidsdeelname. Veel jongeren besluiten pas later te gaan werken en veel ouderen kiezen nog altijd voor een vervroegd pensioen. Dit is voor de overheid aanleiding om een onderzoek uit te laten voeren naar de ontwikkeling van de omvang van de beroepsgeschikte bevolking (bevolking tussen 15 en 70 jaar) en de arbeidsdeelname. De overheid wil aan de hand van het onderzoek haar beleid aanpassen. Figuur 1 is afkomstig uit het onderzoek.$$, 'inline'),
  ('8d29c1cd-d78d-4f43-8bba-0864f343cc61', '55a29243-fb93-4dcc-9522-2916f163ec57', $$figuur 1: prognose beroepsgeschikte bevolking en arbeidsdeelname 2020-2045$$,
   $$economie-vwo-2021-iii-maatregelen-die-werken-context2.png$$,
   $$Figuur 1 Prognose ontwikkelingen 2020-2045
Linkeras: ontwikkeling beroepsgeschikte bevolking (2020 = 100), schaal 90-108; rechteras: arbeidsdeelname (in %), schaal 65-74; horizontaal: 2020-2045.
Legenda: doorgetrokken lijn = de arbeidsdeelname; stippellijn = de beroepsgeschikte bevolking$$, 'inline'),
  ('208e5a85-4c18-411e-85ea-551e9528f0d1', '55a29243-fb93-4dcc-9522-2916f163ec57', $$formule arbeidsdeelname$$,
   $$economie-vwo-2021-iii-maatregelen-die-werken-context3.png$$,
   $$Arbeidsdeelname = (Beroepsbevolking in personen / Beroepsgeschikte bevolking) x 100%$$, 'inline'),
  ('1e04cf54-4607-4c1e-a3b0-a75a127c35cd', '55a29243-fb93-4dcc-9522-2916f163ec57', $$twee beweringen over economische gevolgen van dalende arbeidsdeelname$$,
   $$economie-vwo-2021-iii-maatregelen-die-werken-context4.png$$,
   $$In het onderzoek staan twee beweringen over de economische gevolgen van de ontwikkeling van de arbeidsdeelname van 2020 tot 2040:
1 “De ontwikkeling van de arbeidsdeelname in figuur 1 kan op termijn leiden tot loonkosteninflatie.
2 Zonder groei van de arbeidsproductiviteit kan de loonkostenstijging, vanwege het open karakter van de economie, een negatief effect hebben op de economische groei van het land.”$$, 'inline'),
  ('2807447e-61e3-43ce-85f5-771acbb2323d', '55a29243-fb93-4dcc-9522-2916f163ec57', $$econoom: stijgende lonen hoogopgeleiden, dalend aanbod oudere hoogopgeleiden$$,
   $$economie-vwo-2021-iii-maatregelen-die-werken-context5.png$$,
   $$Uit het onderzoeksrapport blijkt dat de arbeidsdeelname vooral daalt bij jongeren (18 tot 25 jaar). Econoom Van de Ven kijkt hierbij specifiek naar de hoogopgeleide jongeren die later toetreden tot de arbeidsmarkt. Zij vindt deze ontwikkeling zorgwekkend en voorziet nog meer problemen: “De dalende arbeidsdeelname van de hoogopgeleide jongeren zorgt voor een stijging van de lonen voor hoogopgeleiden. Hierdoor kan het aanbod van arbeid van de oudere hoogopgeleiden (de groep met een leeftijd tussen de 55 en 70 jaar) nu en over 40 jaar ook dalen.”$$, 'inline'),
  ('2c2fc4cd-7734-4182-b63e-a4ce7afff248', '55a29243-fb93-4dcc-9522-2916f163ec57', $$maatregel: pensioenuitkering na 45 gewerkte jaren$$,
   $$economie-vwo-2021-iii-maatregelen-die-werken-context6.png$$,
   $$Volgens de econoom moet de arbeidsdeelname van zowel de jongere als de oudere hoogopgeleiden omhoog om op de middellange termijn te kunnen voldoen aan de vraag naar hoogopgeleide arbeidskrachten. In het onderzoeksrapport staat de volgende maatregel: “De pensioenuitkering, die gefinancierd wordt via het kapitaaldekkingsstelsel, begint niet langer voor iedereen bij 70 jaar, maar nadat men 45 jaar heeft gewerkt.”$$, 'inline'),
  ('23f381c2-7003-4dc6-aa3d-e72172289a27', '55a29243-fb93-4dcc-9522-2916f163ec57', $$econoom: gevolgen voor houdbaarheid pensioenstelsel en arbeidsproductiviteit$$,
   $$economie-vwo-2021-iii-maatregelen-die-werken-context7.png$$,
   $$Door deze maatregel zal de arbeidsdeelname van de hoogopgeleiden toenemen. De econoom vindt echter dat in het rapport geen rekening is gehouden met het optreden van andere gevolgen. Ze verwacht een positief gevolg voor de houdbaarheid van het pensioenstelsel en een mogelijk negatief gevolg voor de gemiddelde arbeidsproductiviteit.$$, 'inline'),
  ('75e0f6c6-beed-4bea-b057-bef363d6f7ac', 'e1cfeeb9-5b22-45d8-aa89-02c8a4528352', $$inleiding: CFA-landen vormen een monetaire unie$$,
   $$economie-vwo-2021-iii-de-afrikaanse-euro-variant-context1.png$$,
   $$Veertien West- en Centraal-Afrikaanse landen (de CFA-landen) vormen samen een monetaire unie. Ze hebben afgesproken een gemeenschappelijke munteenheid te gebruiken: de CFA-frank. In de onderlinge handel wordt met deze CFA-frank betaald. De CFA-landen handelen ook buiten de muntunie: ongeveer 20% van de export van de CFA-landen gaat naar de Verenigde Staten (VS).$$, 'inline'),
  ('07687231-093f-4873-8750-e59b735dc045', 'e1cfeeb9-5b22-45d8-aa89-02c8a4528352', $$journaliste: tekort lopende rekening, toch appreciatie CFA-frank$$,
   $$economie-vwo-2021-iii-de-afrikaanse-euro-variant-context2.png$$,
   $$Een journaliste schrijft hierover: “Ondanks de lage inflatie in de CFA-landen is er sprake van een groeiend tekort op de gezamenlijke lopende rekening van de CFA-landen met de VS. Dit heeft echter niet geleid tot een depreciatie van de CFA-frank ten opzichte van de dollar. In tegendeel, de CFA-frank is geapprecieerd ten opzichte van de dollar.”$$, 'inline'),
  ('8853b385-07a7-4673-9e3d-a6133265fb6d', 'e1cfeeb9-5b22-45d8-aa89-02c8a4528352', $$beleid gericht op lage inflatie bij hoge nominale rente$$,
   $$economie-vwo-2021-iii-de-afrikaanse-euro-variant-context3.png$$,
   $$De journaliste schrijft dat de CFA-overheden in overleg met de centrale bank hun beleid van de afgelopen jaren gericht hebben op het laag houden van de inflatie bij een relatief hoge nominale rente. Dit heeft geleid tot zowel een positief effect als een negatief effect op de totale investeringen in de CFA-landen.$$, 'inline'),
  ('c322e73b-f5df-433a-8a71-5548141f8096', 'e1cfeeb9-5b22-45d8-aa89-02c8a4528352', $$centrale bank wil de munt laten depreciëren via interventie$$,
   $$economie-vwo-2021-iii-de-afrikaanse-euro-variant-context4.png$$,
   $$De centrale bank van de CFA-landen wil de economische groei stimuleren. De journaliste beweert: “De centrale bank zal de eigen munt depreciëren door direct te interveniëren op de valutamarkt. Hierdoor zal de omvang van de valutareserve veranderen.”$$, 'inline'),
  ('19b36d21-c51a-4d3b-aea4-2b2503d384e3', 'e1cfeeb9-5b22-45d8-aa89-02c8a4528352', $$importheffingen tegen het tekort op de lopende rekening$$,
   $$economie-vwo-2021-iii-de-afrikaanse-euro-variant-context5.png$$,
   $$Ondanks het voeren van begrotingsbeleid en monetair beleid blijft er een tekort op de gezamenlijke lopende rekening van de CFA-landen. De overheden van de CFA-landen willen door middel van importheffingen op buitenlandse goederen het tekort op de gezamenlijke lopende rekening op korte termijn verminderen. De journaliste schrijft dat hierdoor het saldo lopende rekening op langere termijn juist kan verslechteren.$$, 'inline');

